+  id: 'thing',
+  landed: '2026-09-05',
+  version: '60906.9',
+  summary: 'a thing',
+  ${codemod ? `${codemod}: true,` : ''}
+  ${applyStage ? "applyStage: { why: 'repair what pins the old shape', instructions: 'run the suite' }," : ''}
+};
+`;
